WITH (intDiv((toUnixTimestamp64Milli(now64(3)) - 1009810800000) * 25, 60000) % 3110400) AS now_tick SELECT t.weather_id AS weather, t.zone_id AS zone, zn.name AS zone_name, ((t.tick - now_tick) % 3110400 + 3110400) % 3110400 AS ahead FROM weather_timeline t LEFT JOIN (SELECT id, name FROM zone_names WHERE release = (SELECT max(release) FROM captures)) zn ON zn.id = t.zone_id WHERE length(t.weathers) = 1 AND ahead > 0 AND ahead <= 36000 ORDER BY weather, ahead LIMIT 3 BY weather
